      const isNetworkOrTimeout =
        timedOut ||
        (err instanceof Error &&
          (err.name === "AbortError" ||
            err.message.includes("fetch failed") ||
            err.message.includes("ENOTFOUND") ||
            err.message.includes("ETIMEDOUT") ||
            err.message.includes("returned HTTP 5")));

